shell_commands:
python3 - <<'EOF'
p='src/orchestration/orchestratorHelpers.test.ts'
s=open(p).read()
old="""  it('returns the defined side when one operand is undefined', () => {
    const usage: UsageMetadata = {inputTokens: 5, outputTokens: 2, totalTokens: 7};
    expect(accumulateUsage(undefined, usage)).toEqual(usage);
    expect(accumulateUsage(usage, undefined)).toEqual(usage);
  });
"""
new="""  it('returns the reported usage when nothing has accumulated yet', () => {
    const usage: UsageMetadata = {inputTokens: 5, outputTokens: 2, totalTokens: 7};
    expect(accumulateUsage(undefined, usage)).toEqual(usage);
  });

  it('keeps the accumulated usage when a round reports none', () => {
    const usage: UsageMetadata = {inputTokens: 5, outputTokens: 2, totalTokens: 7};
    expect(accumulateUsage(usage, undefined)).toEqual(usage);
  });
"""
assert old in s
open(p,'w').write(s.replace(old,new))
EOF
grep -n "it(" src/orchestration/orchestratorHelpers.test.ts; sed -n 18,22p specs/hal-engine-config-hooks/spec.md
